assert len(ISL) == NK and ISL[FARM_K]["type"] == "wheat" and ISL[FARM_K]["ench"] == "Skyy_Ench_Wheat"
assert len(set(i["type"] for i in ISL)) == NK
SOUL_ORB = "Weapon_Wand_SoulOrb"        # SkyyArmory's Soul Orb (0.3: the Soul Cage totem's core; armory:fn:soulcage ladder place 0)
# the blocks of each island style (vanilla ids, asserted against Assets.zip below): ore node, tree trunk + leaves, fruit, pen rim
STYLE_BLOCKS = {"ore": "Ore_Copper_Stone", "oaktrunk": "Wood_Oak_Trunk", "oakleaf": "Plant_Leaves_Oak", "appletrunk": "Wood_Apple_Trunk",
                "appleleaf": "Plant_Leaves_Apple", "apple": "Plant_Crop_Apple_Block", "hay": "Plant_Hay_Bundle", "cobble": "Rock_Stone_Cobble",
                "mossy": "Rock_Stone_Brick_Mossy"}
SLOTS = 16                              # 0.4.8: one island per tier (ladders up to 15) - 6 inner hexagon places (0.4.x, unchanged) + 10 outer
RING = 48                               # spec 9.1: 6 fixed slots on a hexagon 48 blocks out
RING2 = 104                             # 0.4.8: the outer ring (10 places, 36 degrees apart, between the hexagon's spokes)
NINNER = 6
HALF = [6, 10, 14]                      # Small 13 x 13, Medium 21 x 21, Large 29 x 29 (spec 9.1); index = size - 1
SIZE_NAMES = ["Small", "Medium", "Large"]
HUB_HALF = 6
SLOT_POS = []
for _i in range(NINNER):                # slot 1 = north (-z), then clockwise
    _a = math.radians(-90 + 60 * _i)
    SLOT_POS.append((int(round(RING * math.cos(_a))), int(round(RING * math.sin(_a)))))
SLOT_SRC = [-1] * NINNER                # 0.4.8: where each slot's bridge starts (-1 = the hub, else the inner slot it hangs on)
for _j in range(SLOTS - NINNER):        # 0.4.8: the outer ring, bridged to the nearest inner island
    _a = math.radians(-90 + 18 + 36 * _j)
    SLOT_POS.append((int(round(RING2 * math.cos(_a))), int(round(RING2 * math.sin(_a)))))
    _best = min(range(NINNER), key=lambda _i: (math.hypot(SLOT_POS[-1][0] - SLOT_POS[_i][0], SLOT_POS[-1][1] - SLOT_POS[_i][1]), _i))
    SLOT_SRC.append(_best)
assert len(SLOT_POS) == SLOTS == len(SLOT_SRC)
for _i in range(SLOTS):
    for _j in range(_i + 1, SLOTS):
        _d = math.hypot(SLOT_POS[_i][0] - SLOT_POS[_j][0], SLOT_POS[_i][1] - SLOT_POS[_j][1])
        assert _d - 2 * HALF[2] * math.sqrt(2) > 4 or _d > 2 * HALF[2] + 8, "slots %d / %d overlap at Large" % (_i, _j)
assert RING - HALF[2] - HUB_HALF >= 8, "the hub and a Large island leave a bridge"
# 0.4.21 THE COMBAT ARENAS (Skyy 2026-11-08: "make the combat island bigger, and put walls around it."): their own half widths (rows combat.half.*) and their own slot centres: slot 0 stays,
# slots 1..5 move out along their own spoke - a 51 x 51 island does not fit on the 48-block hexagon. Everything below holds at the rows' maximum half.
CB_HALF_DEF, CB_HALF_MIN, CB_HALF_MAX, CB_WALL_DEF, CB_RING = [12, 18, 25], list(HALF), 28, 4, 70
CB_SLOT_POS = [SLOT_POS[0]] + [(int(round(CB_RING * math.cos(math.radians(-90 + 60 * _i)))), int(round(CB_RING * math.sin(math.radians(-90 + 60 * _i))))) for _i in range(1, NINNER)]
assert all(_a <= _b <= CB_HALF_MAX for _a, _b in zip(CB_HALF_MIN, CB_HALF_DEF)) and CB_HALF_DEF == sorted(CB_HALF_DEF)
for _i in range(NINNER):
    for _j in range(_i + 1, NINNER):
        assert max(abs(CB_SLOT_POS[_i][0] - CB_SLOT_POS[_j][0]), abs(CB_SLOT_POS[_i][1] - CB_SLOT_POS[_j][1])) >= 2 * CB_HALF_MAX + 4, "0.4.21: combat slots %d / %d overlap" % (_i, _j)
    assert max(abs(CB_SLOT_POS[_i][0]), abs(CB_SLOT_POS[_i][1])) - CB_HALF_MAX - HUB_HALF >= 8, "0.4.21: combat slot %d leaves no bridge" % _i
    _ln, _t = math.hypot(*CB_SLOT_POS[_i]), float(HUB_HALF - 1)
    while _t <= _ln - CB_HALF_MAX:
        for _w in (-1, 0, 1):
            _x = int(round(CB_SLOT_POS[_i][0] / _ln * _t - CB_SLOT_POS[_i][1] / _ln * _w))
            _z = int(round(CB_SLOT_POS[_i][1] / _ln * _t + CB_SLOT_POS[_i][0] / _ln * _w))
            for _j in range(NINNER):
                assert _j == _i or max(abs(_x - CB_SLOT_POS[_j][0]), abs(_z - CB_SLOT_POS[_j][1])) > CB_HALF_MAX + 1, "0.4.21: the bridge of combat slot %d crosses slot %d" % (_i, _j)
        _t += 0.5
# 0.4.8: every bridge (hub -> inner, inner -> outer) runs clear of every OTHER island at Large (+ 2 blocks) and of the hub
def _bridge_cells48(i):
    _s = SLOT_SRC[i]
    _ax, _az = (0, 0) if _s < 0 else SLOT_POS[_s]
    _bx, _bz = SLOT_POS[i]
    _ln = math.hypot(_bx - _ax, _bz - _az)
    _ux, _uz = (_bx - _ax) / _ln, (_bz - _az) / _ln
    _t0 = (HUB_HALF - 1) if _s < 0 else HALF[0]
    _out = set()
    _t = float(_t0)
    while _t <= _ln - HALF[0]:
        for _w in (-1, 0, 1):
            _out.add((int(round(_ax + _ux * _t - _uz * _w)), int(round(_az + _uz * _t + _ux * _w))))
        _t += 0.5
    return _out
for _i in range(SLOTS):
    for (_x, _z) in _bridge_cells48(_i):
        for _j in range(SLOTS):
            if _j in (_i, SLOT_SRC[_i]):
                continue
            assert max(abs(_x - SLOT_POS[_j][0]), abs(_z - SLOT_POS[_j][1])) > HALF[2] + 2, "0.4.8: the bridge of slot %d crosses slot %d" % (_i, _j)
        if SLOT_SRC[_i] >= 0:
            assert abs(_x) + abs(_z) > HUB_HALF + 4, "0.4.8: an outer bridge crosses the hub"
EXT48 = RING2 + HALF[2] + 2
assert CB_RING + CB_HALF_MAX + 1 <= EXT48, "0.4.21: the combat arenas stay inside the loaded region"
CHUNKS = sorted(set(((REGION_X + dx) >> 5, (REGION_Z + dz) >> 5) for dx in range(-EXT48, EXT48 + 1) for dz in range(-EXT48, EXT48 + 1)))
assert len(CHUNKS) <= 81, CHUNKS        # 0.4.8: the full region (a paint loads only the chunks its blocks are in)
assert EXT48 < 512 - 8, "0.4.8: a region stays inside its 1,024 blocks"
# 0.3: every region is the Farming region moved by 1024 x (kind - 2) on x = 32 x (kind - 2) chunks (1024 is a whole number of chunks)
assert 1024 % 32 == 0
for _k in range(NK):
    _ch = sorted(set(((1024 * _k + dx) >> 5, dz >> 5) for dx in range(-EXT48, EXT48 + 1) for dz in range(-EXT48, EXT48 + 1)))
    assert _ch == [(cx + 32 * (_k - FARM_K), cz) for (cx, cz) in CHUNKS], _k
