# 0.4.7: the run-once markers of the islands whose centre fix is done (world "skyy-shard-<pkey>"), saved at once
M(fill, r"""
public static int markFixed(String wn, int kd, java.util.HashSet fixed) {
  if (fixed == null || fixed.size() == 0 || wn == null || !wn.startsWith("skyy-shard-") || wn.length() <= 11) return 0;
  String k = wn.substring(11);
  int n = 0;
  String done = "";
  String caves = "";   // 0.4.8: slot + 100 = the cave rebuild of that island
  String caves2 = "";   // 0.4.18: slot + 200 = the natural cave rebuild (marker 2)
  String arenas = "";   // 0.4.21: arenaTag (>= 300) = the combat arena rebuild (marker <half>:<wall>)
  String snapA = null;
  boolean refusedA = false;
  String snap = null;
  boolean refused = false;
  @PKG@.ShStore.LOCK.lock(); try {
    java.util.Properties p = @PKG@.ShStore.get(k);
    if (p == null) return 0;
    java.util.Iterator it = fixed.iterator();
    while (it.hasNext()) {
      int s = ((Integer) it.next()).intValue();
      if (s >= 300) {   // 0.4.21: the combat arena is rebuilt at its new size
        int cs = @PKG@.ShGeo.arenaSlotOf(s);
        if (!@PKG@.ShMath.hasIsland(kd, p, cs)) continue;
        String akey = @PKG@.ShMath.ik(kd, cs, "arena");
        String am = @PKG@.ShGeo.arenaMarkOf(s);   // fix (critic): what this paint built
        if (am.equals(p.getProperty(akey))) continue;
        if (refusedA) continue;
        if (snapA == null) { snapA = @PKG@.ShStore.snapArena(k); if (snapA == null) { refusedA = true; continue; } }   // History copy FIRST (byte-checked)
        p.setProperty(akey, am);
        arenas = arenas + " " + (cs + 1) + "=" + am;
        n++;
        continue;
      }
      if (s >= 200) {   // 0.4.18: the old box cave is cleared - the island is the natural cave now
        int cs = s - 200;
        if (!@PKG@.ShMath.hasIsland(kd, p, cs)) continue;
        String ckey = @PKG@.ShMath.kk(kd, "i" + cs + ".cave");
        String cur = p.getProperty(ckey);
        if ("2".equals(cur)) continue;
        if (!"1".equals(cur) && !fixed.contains(Integer.valueOf(cs + 100))) continue;   // the 0.4.8 flat-node fix of this island is not done yet
        if (refused) continue;
        if (snap == null) { snap = @PKG@.ShStore.snapCave(k); if (snap == null) { refused = true; continue; } }   // History copy FIRST (byte-checked)
        p.setProperty(ckey, "2");
        caves2 = caves2 + " " + (cs + 1);
        n++;
        continue;
      }
      if (s >= 100) {   // 0.4.8: the old flat Mining island's nodes are cleared - it is a cave now
        int cs = s - 100;
        if (!@PKG@.ShMath.hasIsland(kd, p, cs)) continue;
        String ckey = @PKG@.ShMath.kk(kd, "i" + cs + ".cave");
        if ("1".equals(p.getProperty(ckey)) || "2".equals(p.getProperty(ckey))) continue;   // 0.4.18: 2 = already past this
        p.setProperty(ckey, "1");
        caves = caves + " " + (cs + 1);
        n++;
        continue;
      }
      if (s < 0 || !@PKG@.ShMath.hasIsland(kd, p, s)) continue;
      String key = @PKG@.ShMath.kk(kd, "i" + s + ".centre");
      if ("1".equals(p.getProperty(key))) continue;
      p.setProperty(key, "1");
      done = done + " " + (s + 1);
      n++;
    }
    if (n > 0) {
      String err = @PKG@.ShStore.save(k, p);
      if (err != null) @PKG@.ShCfg.warn("the centre-pad markers of " + k + " could not be saved (" + err + ") - the fix (own blocks only) runs again next time");
      else {
        if (arenas.length() > 0) @PKG@.ShStore.log("arena (SkyyShards @VERSION@) " + k + " " + @PKG@.ShKind.KEYS[kd] + " island(s)" + arenas + ": rebuilt once at the new size, our blocks only; copy " + snapA);
        if (done.length() > 0) @PKG@.ShStore.log("centre " + k + " " + @PKG@.ShKind.KEYS[kd] + " island(s)" + done + ": the old brick pillar is gone, pad 1 is the centre (0.4.7, once)");
        if (caves.length() > 0) @PKG@.ShStore.log("cave " + k + " " + @PKG@.ShKind.KEYS[kd] + " island(s)" + caves + ": the old flat ore nodes are cleared - the island is a copper cave now (0.4.8, once)");
        if (caves2.length() > 0) @PKG@.ShStore.log("cave2 (SkyyShards @VERSION@) " + k + " " + @PKG@.ShKind.KEYS[kd] + " island(s)" + caves2 + ": the old box cave is cleared (our host / ore blocks only) - a natural cave whose mouth meets the bridge (once, marker .cave=2) - History copy " + snap + " - Undo: stop the server, copy it back over shards/" + k + ".properties (the markers go back; the blocks stay - SkyyShards 0.4.17 paints its box again)");
      }
    }
  } finally { @PKG@.ShStore.LOCK.unlock(); }
  if (refusedA) @PKG@.ShCfg.warnOnce("arenasnap:" + k, "the 0.4.21 arena rebuild marker of " + k + " is waiting: its History copy could not be written (the arena is rebuilt; it is marked next time)");
  if (refused) @PKG@.ShCfg.warnOnce("cavesnap:" + k, "the 0.4.18 cave rebuild marker of " + k + " is waiting: its History copy could not be written (the cave is rebuilt; it is marked next time)");
  return n;
}""")
