M(core, r"""
public static String placeAt(java.util.UUID u, String k, int kd, int slot, int ci, int si, int dx, int dz, @IC@[] cs) {   // 0.4.13: a pole placed by hand where it stands
  Object[] o = new Object[1];
  String no = start(u, k, kd, cs, o);
  if (no != null) return no;
  java.util.Properties p = (java.util.Properties) o[0];
  if (slot < 0 || slot >= @PKG@.ShMath.SLOTS) return "-Pick an island first.";
  if (ci < 0 || ci >= cs.length || cs[ci] == null) return "-That totem is not in your inventory any more.";
  @IS@ it = cs[ci].getItemStack((short) si);
  String id = it == null || it.isEmpty() ? null : it.getItemId();
  int ti = @PKG@.ShTotem.itemIdx(id);
  if (ti < 0) return "-That totem is not in your inventory any more.";
  long now = now();
  @BD@ d = @PKG@.ShTotem.docOf(it);
  String[] f = @PKG@.ShTotem.fromDoc(d, id, now);
  if (f == null) return "-That totem's document does not match its item - ask an admin (totem.log).";
  if (!@PKG@.ShTotem.accepts(ti, kd)) return "-The " + @PKG@.ShTotem.NAMES[ti] + " works in the " + @PKG@.ShTotem.kindsOf(ti) + " Shard - not in this one.";
  if (@PKG@.ShTotem.handHeld(f)) return "-" + @PKG@.ShTotem.name(f) + " is hand-held: right-click it anywhere to use it. Make it a Totem Pole II at the Totem Bench (Make pole tab) to place it.";   // 0.4 (spec 9.3.1); 0.4.7 tab name
  String docUid = @PKG@.ShTotem.dstr(d, "uid");
  if (f[5].length() == 0) f[5] = @PKG@.ShTotem.newUid();
  String[] g8 = new String[8];
  for (int i = 0; i < 8; i++) g8[i] = i < f.length && f[i] != null ? f[i] : "";
  f = g8;
  f[7] = dx + ";" + dz;
  String res;
  @PKG@.ShStore.LOCK.lock(); try {
    int[] dup = uidAt(p, docUid);   // fix3: this exact totem (uid) is placed already = a copy left by a crash -> removed, never placed twice
    if (dup != null) {
      boolean gone = @PKG@.ShInv.takeSlot(cs, ci, si, id, docUid);
      tlog(u + " " + k + " DUPLICATE uid " + docUid + " (placed on " + @PKG@.ShKind.KEYS[dup[2]] + " island " + (dup[0] + 1) + " pad " + (dup[1] + 1) + ") - copy removed " + gone);
      return "-This totem is already placed on island " + (dup[0] + 1) + " - this was a duplicate copy" + (gone ? " and was removed." : ".") + " (totem.log)";
    }
    if (!@PKG@.ShMath.hasIsland(kd, p, slot)) return "-That slot has no island yet.";
    int sz = @PKG@.ShMath.size(kd, p, slot);
    String[] e = @PKG@.ShTotem.entries(kd, p, slot);
    int pads = @PKG@.ShMath.pads(sz);
    if (e.length >= pads) return "-This island has all its totems (" + e.length + " of " + pads + "). Grow it or pick a totem up first.";
    int hh = @PKG@.ShGeo.half(kd, sz);   // 0.4.21: the combat arena's own size
    if (dx <= -hh || dx >= hh || dz <= -hh || dz >= hh) return "-That spot is off the island's farmland - a totem stands inside the island.";
    if (dx >= -1 && dx <= 1 && dz >= -1 && dz <= 1) return "-The island's centre holds its totem pads - stand it on the farmland around it (or place it from the shard menu).";
    for (int i = 0; i < e.length; i++) { int[] q = @PKG@.ShTotem.posOf(@PKG@.ShTotem.parse(e[i])); if (q != null && q[0] == dx && q[1] == dz) return "-Another totem stands right there - pick another spot."; }
    @PKG@.ShMath.settle(kd, p, slot, now);
    if (!@PKG@.ShInv.takeSlot(cs, ci, si, id, docUid)) return "-That totem moved in your inventory - try again.";
    java.util.Properties old = new java.util.Properties();
    old.putAll(p);
    String[] ne = new String[e.length + 1];
    for (int i = 0; i < e.length; i++) ne[i] = e[i];
    ne[e.length] = @PKG@.ShTotem.fmt(f);
    @PKG@.ShTotem.setEntries(kd, p, slot, ne);
    String err = @PKG@.ShStore.save(k, p);
    if (err != null) {
      p.clear(); p.putAll(old);
      boolean back = @PKG@.ShInv.giveStack(cs, @PKG@.ShTotem.stack(f, now));
      tlog(u + " " + k + " place " + @PKG@.ShTotem.fmt(f) + " SAVE FAILED " + err + " - item back " + back);
      return "-The totem could not be saved - " + (back ? "it is back in your inventory." : "ask an admin (totem.log).");
    }
    tlog(u + " " + k + (kd == FK ? "" : " " + @PKG@.ShKind.KEYS[kd]) + " place slot " + slot + " by hand at " + dx + "," + dz + " " + @PKG@.ShTotem.fmt(f));
    res = "+Placed " + @PKG@.ShTotem.name(f) + " here on island " + (slot + 1) + " (" + (e.length + 1) + " of " + pads + " totems) - it works the crops in its range around this spot.";
  } finally { @PKG@.ShStore.LOCK.unlock(); }
  @PKG@.ShWorld2.repaint(k, kd);
  return res;
}""")
M(core, r"""
public static int[] spotFor(java.util.Properties p, int kd, int bx, int bz) {
  for (int s = 0; s < @PKG@.ShMath.SLOTS; s++) {
    if (!@PKG@.ShMath.hasIsland(kd, p, s)) continue;
    int h = @PKG@.ShGeo.half(kd, @PKG@.ShMath.size(kd, p, s));   // 0.4.21
    int dx = bx - (@PKG@.ShGeo.ox(kd) + @PKG@.ShGeo.sxk(kd, s));
    int dz = bz - (@PKG@.ShGeo.OZ + @PKG@.ShGeo.szk(kd, s));
    if (dx >= -h && dx <= h && dz >= -h && dz <= h) return new int[] { s, dx, dz };
  }
  return null;
}""")   # 0.4.13: the island (slot) + spot (dx, dz from its centre) of block column (bx, bz) in shard kd, or null
