M(core, r"""
public static int auraSet(java.util.UUID u, String k, int kd, int slot, int pad, long until) {
  if (u == null || k == null) return -1;
  java.util.Properties p = @PKG@.ShStore.get(k);
  if (p == null) return -1;
  String[] f;
  int sz = 1;
  @PKG@.ShStore.LOCK.lock(); try { f = at(kd, p, slot, pad); if (f != null) sz = @PKG@.ShMath.size(kd, p, slot); } finally { @PKG@.ShStore.LOCK.unlock(); }
  if (f == null) return -1;
  int r = @PKG@.ShTotem.range(f, now());
  double[] c = @PKG@.ShGeo.totemSpot(kd, slot);
  int[] o = @PKG@.ShTotem.posOf(f);   // a pole placed by hand: its own spot (dx, dz from the island centre)
  AURA.put(u, new Object[] { @PKG@.ShWorlds.name(k), new double[] { c[0], (double) @PKG@.ShGeo.Y, c[2], (double) r, (double) until, (double) (sz < 1 ? 1 : (sz > 3 ? 3 : sz)),
      (double) (o == null ? 0 : o[0]), (double) (o == null ? 0 : o[1]), (double) @PKG@.ShGeo.half(kd, sz) } });
  return r;
}""")
M(core, r"""
public static String auraToggle(java.util.UUID u, String k, int kd, int slot, int pad) {
  if (u == null) return "";
  if (AURA.remove(u) != null) return "=Range hidden.";
  int r = auraSet(u, k, kd, slot, pad, System.currentTimeMillis() + AURA_OPEN_MS);
  if (r < 0) return "-That totem is gone - the page is up to date now.";
  int s = @PKG@.ShCfg.AURA_SEC;
  return "=Range " + r + " blocks: a ring marks the edge, puffs mark the cells it works. Only you see it" + (s > 0 ? " - it stays " + s + " s after you close this page." : ".");
}""")
M(core, r"""
public static void auraKeep(java.util.UUID u, String k, int kd, int slot, int pad) {
  if (u == null || AURA.get(u) == null) return;
  auraSet(u, k, kd, slot, pad, System.currentTimeMillis() + AURA_OPEN_MS);
}""")
M(core, r"""
public static void auraClose(java.util.UUID u) {
  if (u == null) return;
  Object o = AURA.get(u);
  if (!(o instanceof Object[])) return;
  int s = @PKG@.ShCfg.AURA_SEC;
  if (s <= 0) { AURA.remove(u); return; }
  double[] c = (double[]) ((Object[]) o)[1];
  long until = System.currentTimeMillis() + 1000L * (long) s;
  if ((long) c[4] > until) c[4] = (double) until;
}""")
# 0.4.7 (Skyy 2026-10-23 "tier up should work in the totem pole"): the 0.4 ShCore.upgrade line ("Totems tier up at the ... Totem Bench") is
# gone - the totem page tiers up the placed totem itself (ShCore.tierUpPlaced, after the bench tier-up below)
# ---- crafting (Craft tab). A recipe "Item:qty,Item:qty;coins" -> Object[]{ String[] ids, long[] qty, Long coins } or null (bad / empty)
# fix2 (critic shards03 2nd round): the same id named twice is ONE row (quantities added, first place kept), so the per-row item check
# counts the sum and a refund (giveBack per id) can never hand the kept stacks back twice
M(core, r"""
public static Object[] recipe(String txt) {
  if (txt == null || txt.trim().length() == 0) return null;
  try {
    String t = txt.trim();
    long coins = 0L;
    int sc = t.indexOf(';');
    if (sc >= 0) { String c = t.substring(sc + 1).trim(); if (c.length() > 0) coins = Long.parseLong(c); t = t.substring(0, sc).trim(); }
    if (coins < 0L) return null;
    String[] a = t.length() == 0 ? new String[0] : t.split(",");
    String[] ids0 = new String[a.length];
    long[] q0 = new long[a.length];
    int m = 0;
    for (int i = 0; i < a.length; i++) {
      String[] b = a[i].trim().split(":");
      if (b.length != 2 || b[0].trim().length() == 0) return null;
      String id = b[0].trim();
      long n = Long.parseLong(b[1].trim());
      if (n < 1L || n > 100000L) return null;
      int at = -1;
      for (int j = 0; j < m; j++) if (ids0[j].equals(id)) at = j;
      if (at >= 0) { q0[at] += n; if (q0[at] > 100000L) return null; }
      else { ids0[m] = id; q0[m] = n; m++; }
    }
    String[] ids = new String[m];
    long[] q = new long[m];
    for (int i = 0; i < m; i++) { ids[i] = ids0[i]; q[i] = q0[i]; }
    if (ids.length == 0 && coins == 0L) return null;
    return new Object[] { ids, q, Long.valueOf(coins) };
  } catch (Throwable x) { return null; }
}""")
# rebirths of a profile (SkyyRebirth rebirth:fn:count): -2 = still loading, 0 = none / no SkyyRebirth
M(core, r"""
public static int rebirths(String pk) {
  try {
    java.util.function.Function g = @PKG@.ShPay.f("rebirth:fn:count");
    if (g == null) return 0;
    Object r = g.apply(pk);
    if (r == null) return -2;
    return r instanceof Number ? ((Number) r).intValue() : 0;
  } catch (Throwable t) { return 0; }
}""")
