# BUY THE NEXT TIER (spec 9.1): tier index ti (0 = T1) must be the first tier not owned (the path is in order); it goes into the first free slot,
# Small, no totems, Automated when the shard is. Cost = isl.buyHours at its tier level + isl.buyItems.<kind> (T2 Lettuce = 3,500 + 128 Lettuce
# + 32 Lettuce Seeds - Skyy's "money, lettuce, and lettuce seeds")
M(core, r"""
public static String buyIsland0(java.util.UUID u, String k, int kd, int ti, @IC@[] cs) {
  if (!@PKG@.ShCfg.ON) return "-Shards are switched off on this server.";
  java.util.Properties p = @PKG@.ShStore.get(k);
  if (p == null) return "-This shard's file could not be read.";
  if (cs == null) return "-Your inventory could not be read - try again.";
  String no = gateOwn(u, k, kd, p);
  if (no != null) return no;
  if (ti < 0 || ti >= @PKG@.ShIsl.LADN[kd]) return "-Pick an island first.";
  int t = @PKG@.ShIsl.LAD0[kd] + ti;
  double cv = @PKG@.ShCfg.curve(@PKG@.ShIsl.band(@PKG@.ShIsl.TIER[t]));   // the bridge asked outside the lock
  int zneed = kd == @PKG@.ShCombat.CK ? @PKG@.ShCombat.need(ti) : 0;   // 0.4.11 (spec 10): Zone N needs class level combat.zoneLevel.N
  if (zneed > 0) {
    int clv = @PKG@.ShIsl.level(u, kd);
    if (clv == -2) return "-Your class level could not be read right now - try again in a moment.";
    if (clv == -1) return "-The " + @PKG@.ShIsl.tname(t) + " island needs class level " + zneed + " - no class levels on this server (Server Setup -> Shards -> Combat islands: 0 = any).";   // fix (critic): no skills mod = locked, never open
    if (clv < zneed) return "-The " + @PKG@.ShIsl.tname(t) + " island needs class level " + zneed + " (you: " + clv + ").";
  }
  String zno = @PKG@.ShIsl.zoneNo(u, kd, t);   // 0.4.23: a locked zone's islands wait (Foraging; asked before the lock)
  if (zno != null) return zno;
  int slot;
  long ver;
  @PKG@.ShStore.LOCK.lock(); try {   // 0.4.14: decide under the lock, pay outside it (purchaseM commits while nothing was saved since)
    if (@PKG@.ShIsl.owns(kd, p, t)) return "=You own the " + @PKG@.ShIsl.tname(t) + " island already.";   // 0.4.30: or that ore on its zone's quarry
    if (@PKG@.ShIsl.zoned(kd) && @PKG@.ShIsl.zoneSlot(kd, p, @PKG@.ShIsl.zoneOf(t)) >= 0) return @PKG@.ShIsl.mineKd(kd) ? "-" + @PKG@.ShIsl.NAME[t] + " is an upgrade of your Zone " + @PKG@.ShIsl.zoneOf(t) + " quarry now - add it on the quarry's Ores row."
        : "-" + @PKG@.ShIsl.NAME[t] + " is an upgrade of your Zone " + @PKG@.ShIsl.zoneOf(t) + " " + @PKG@.ShIsl.ZW[kd] + " now - add it on the island's " + @PKG@.ShIsl.ROWN[kd] + " row.";   // 0.4.30: one island a zone; 0.4.31: every zoned kind
    int nx = @PKG@.ShIsl.nextTier(kd, p);
    if (nx != ti) return nx < 0 ? "=You own every island of this shard." : "-Buy the " + @PKG@.ShIsl.tname(@PKG@.ShIsl.LAD0[kd] + nx) + " island first (islands come in tier order).";
    slot = @PKG@.ShIsl.freeSlot(kd, p);
    if (slot < 0) return "=This shard has no room for another island.";
    ver = @PKG@.ShStore.ver(k);
  } finally { @PKG@.ShStore.LOCK.unlock(); }
  long coins = @PKG@.ShIsl.coins(@PKG@.ShCfg.BUY_H, cv);
  Object[] mats = @PKG@.ShIsl.mats(kd, t, @PKG@.ShCfg.BUY_ITEMS[kd], 0, 1L);
  long tn = now();
  String[] keys = new String[] { @PKG@.ShMath.ik(kd, slot, "type"), @PKG@.ShMath.ik(kd, slot, "size"), @PKG@.ShMath.ik(kd, slot, "last"), @PKG@.ShMath.ik(kd, slot, "stored") };
  String[] vals = new String[] { @PKG@.ShIsl.KEY[t], "1", String.valueOf(tn), "0" };
  String r = purchaseM(u, k, kd, p, cs, mats, coins, keys, vals, "island", @PKG@.ShKind.KEYS[kd] + " buy " + @PKG@.ShIsl.KEY[t] + " island in slot " + (slot + 1), ver);
  if (r != null) return r;
  @PKG@.ShWorld2.repaint(k, kd);
  return "+The " + @PKG@.ShIsl.tname(t) + " island is yours (Small). Put a worker totem on it (Totems tab) so it makes items.";
}""")
