def tup_bind(ident):
    """0.4.7: the Tier up click carries what the page showed: island, pad, tier, type, uid (ShCore.tierUpPlaced re-checks every one)"""
    return ('  ev.addEventBinding(@BT@.Activating, "#%s", @EVD@.of("a", "tup:" + this.tIsl + ":" + this.tpad + ":" + this.dTier + ":" + this.dType'
            ' + ":" + this.dUid));' % ident)
