    v.extend(wpic[pic]); v.extend(wrg[1 if aura else 0])
    if give:
        v.extend(wsdg)
    if take:
        v.extend(wsdt)
    if not give and not take:
        v.extend(wsdn)
    if boost == "on":
        v.extend(wboi)
    if boost == "can":
        v.extend(wbob)
    else:
        v.extend(wbon)
    if tier:
        v.extend(wtub)
    for _i in range(2):
        if mods[_i]:
            v.extend(wms[_i][0])
            if owner:
                v.extend(wms[_i][1])
    if owner and not all(mods):
        for _i in range(len(MODS)):
            v.extend(wml[_i])
    v.extend(wpk if owner else wvw)
    v.extend(wft)
    v.check(W)
    return v


