def _ckj(name):
    return CKA[name].java("b")


def _tree_pass(back):
    """the trees of one half (back = behind the centre pads), back to front; a regrowing tree = its stump"""
    return "\n".join([
        "  {",
        "    int sz = this.ckSz < 1 ? 1 : (this.ckSz > 3 ? 3 : this.ckSz);",
        "    int[] ox = sz >= 3 ? CKX3 : (sz == 2 ? CKX2 : CKX1); int[] oy = sz >= 3 ? CKY3 : (sz == 2 ? CKY2 : CKY1); int[] od = sz >= 3 ? CKO3 : (sz == 2 ? CKO2 : CKO1);",
        "    int[] ow = sz >= 3 ? CKW3 : (sz == 2 ? CKW2 : CKW1); int cyy = CKCY[sz - 1];",
        "    for (int q = 0; q < od.length; q++) {",
        "      int i = od[q];",
        "      int tw = i < ow.length ? ow[i] : CKTW[sz - 1]; int th = tw * 140 / 110;",
        "      if (i >= this.ckTn || i >= ox.length || (oy[i] <= cyy) != %s) continue;" % ("true" if back else "false"),
        "      String tex = this.ckGrow != null && i < this.ckGrow.length && this.ckGrow[i] ? (this.ckTexB != null && i < this.ckTexB.length && this.ckTexB[i] != null ? this.ckTexB[i] : this.ckStump)"
        " : (this.ckTexA != null && i < this.ckTexA.length && this.ckTexA[i] != null ? this.ckTexA[i] : this.ckTree);",   # 0.4.24: a quarry node's picture per spot
        '      b.appendInline("%s", %s);' % (CK_SCN, CK_J_TREE),
        "    }",
        "  }"])


_ck_j = [_ckj("frame"), "  if (this.ckMode == 1) {", _ckj("mapb1"), "  } else {", _ckj("mapb0"), "  }", "  if (this.ckMode == 2) {", _ckj("frame2b"), "  } else {", _ckj("frame2"), "  }",   # 0.4.27
         _ck_jset(CKP + "ChipT", "this.ckChip"), _ck_jset(CKP + "Info", "this.ckInfo"),
         _ck_jset(CKP + "Title", '(this.ckMine ? "MINING SHARD" : (this.ckFarm ? "FARMING SHARD" : (this.ckTown ? "COMBAT SHARD" : (this.kind == @PKG@.ShClk.RNK ? "RANCHING SHARD" : (this.kind == @PKG@.ShClk.ORK ? "ORCHARD SHARD" : "FORAGING SHARD")))))'),   # 0.4.25 / 0.4.26 / 0.4.28
         _ck_bind(CKP + "MapB", '(this.ckMode == 1 ? "kisl" : "kmap")'), _ck_bind(CKP + "MenuB", '(this.ckMode == 2 ? "kisl" : "kup")'), _ck_bind(CKP + "Close", '"close"'),
         "  if (this.ckMode == 2) {"] + UP2_J + ["  } else if (this.ckMode == 1 && this.ckMine) {"] + _QMAP_J + ["  } else if (this.ckMode == 1 && this.ckTown) {"] + _TMAP_J + \
         ["  } else if (this.ckMode == 1 && this.kind == @PKG@.ShClk.RNK) {"] + RO_MAP_J["rmap"] + ["  } else if (this.ckMode == 1 && this.kind == @PKG@.ShClk.ORK) {"] + RO_MAP_J["omap"] + [   # 0.4.28   # 0.4.27: the upgrades view   # 0.4.26: the town map
         "  } else if (this.ckMode == 1) {", "  if (this.ckFarm) {", _ckj("fmap"), "  } else {", _ckj("map"), "  }"]   # 0.4.25: the farm map
for _i in range(0, 15, 3):   # 0.4.31: the Foraging / Farming maps = one card a zone
    _ck_j += ["  if (this.ckMLock[%d]) {" % _i, _ckj("mlock%d" % _i), "  }",
              "  if (this.ckMB[%d] == 1) {" % _i, _ckj("mopen%d" % _i), _ck_bind(CKP + "M%dX" % _i, '"km%d"' % _i),
              "  } else if (this.ckMB[%d] == 2) {" % _i, _ckj("mbuy%d" % _i), _ck_bind(CKP + "M%dX" % _i, '"kb%d"' % _i), "  }",
              _ck_jset(CKP + "M%dN" % _i, "this.ckMN[%d]" % _i), _ck_jset(CKP + "M%dS" % _i, "this.ckMS[%d]" % _i)]
for _z in range(5):
    _ck_j.append(_ck_jset(CKP + "Z%dS" % _z, "this.ckZS[%d]" % _z))
_ck_j += ["  } else {", _ckj("left")]
for _s in (1, 2, 3):
    _ck_j += ["  if (this.ckSz == %d) {" % _s, "  if (this.ckMine) {", _ckj("qisl%d" % _s), "  } else if (this.ckTown) {", _ckj("tisl%d" % _s), "  } else {", _ckj("isl%d" % _s), "  }"]   # 0.4.26: the town
    for _j in CK_BACK_DECO:
        _ck_j += ["    if (this.ckDeco > %d) {" % _j, _ckj("deco%d_%d" % (_s, _j)), "    }"]
    _ck_j += ["  }"]
_ck_j += [_tree_pass(True)]
for _s in (1, 2, 3):
    _ck_j += ["  if (this.ckSz == %d) {" % _s]
    for _j in range(5):
        _ck_j += ["    if (this.ckSpN > %d) {" % _j, _ckj("tot%d_%d" % (_s, _j)), "    }"]
    _ck_j += ["    if (this.ckWx > 0) {", "    if (this.ckMine) {", _ckj("qsp%d" % _s), "    } else {", _ckj("wx%d" % _s), "    }", "    }",
              "    if (this.ckMine && this.ckQSm > 0) {", _ckj("qsm%d" % _s), "    }", "  }"]
_ck_j += [_tree_pass(False)]
for _s in (1, 2, 3):
    _ck_j += ["  if (this.ckSz == %d) {" % _s]
